# filename: summarize_with_audit.py
import sqlite3
import pandas as pd
import json
from pathlib import Path
import re

def extract_audit_directives(conn):
    """Extract audit policy directives from the database."""
    directives = {
        'restricted_columns': [],
        'allowed_operations': ['summarize'],  # Default: allow summarization
        'data_handling_rules': [],
        'privacy_requirements': [],
        'format_requirements': []
    }

    cursor = conn.cursor()

    # 1. Check for explicit policy tables
    policy_tables = []
    cursor.execute("SELECT name FROM sqlite_master WHERE type='table';")
    all_tables = [table[0] for table in cursor.fetchall()]

    for table in all_tables:
        table_lower = table.lower()
        if any(keyword in table_lower for keyword in ['policy', 'audit', 'directive', 'rule', 'compliance']):
            policy_tables.append(table)

    print("Searching for audit policies in the database...")

    for table in policy_tables:
        print(f"  Checking table: {table}")
        try:
            # Get all data from policy tables
            cursor.execute(f"SELECT * FROM {table}")
            rows = cursor.fetchall()

            for row in rows:
                row_text = ' '.join([str(cell) for cell in row if cell])
                row_lower = row_text.lower()

                # Look for directives about sheet1
                if 'sheet1' in row_lower:
                    if 'restrict' in row_lower or 'hide' in row_lower or 'mask' in row_lower:
                        # Try to extract column names
                        col_matches = re.findall(r'column[\s:]*([\w_]+)', row_lower, re.IGNORECASE)
                        if col_matches:
                            directives['restricted_columns'].extend(col_matches)

                    if 'summar' in row_lower:
                        if 'not' in row_lower or 'prohibit' in row_lower or 'forbid' in row_lower:
                            directives['allowed_operations'] = []

                    # Extract any data handling rules
                    if 'rule' in row_lower or 'requirement' in row_lower:
                        directives['data_handling_rules'].append(row_text)

        except Exception as e:
            print(f"    Error reading table {table}: {e}")

    # 2. Check sheet1 itself for embedded directives
    cursor.execute("PRAGMA table_info(sheet1);")
    sheet1_cols = [col[1] for col in cursor.fetchall()]

    # Look for directive columns
    directive_cols = []
    for col in sheet1_cols:
        col_lower = col.lower()
        if any(keyword in col_lower for keyword in ['directive', 'policy', 'audit', 'note', 'comment', 'instruction']):
            directive_cols.append(col)

    if directive_cols:
        print(f"  Found potential directive columns in sheet1: {directive_cols}")

        for col in directive_cols:
            cursor.execute(f"SELECT DISTINCT {col} FROM sheet1 WHERE {col} IS NOT NULL")
            distinct_values = cursor.fetchall()

            for value in distinct_values:
                if value[0]:
                    val_str = str(value[0]).lower()
                    if any(keyword in val_str for keyword in ['confidential', 'sensitive', 'restricted', 'private']):
                        # This might indicate the entire row or related data is sensitive
                        directives['privacy_requirements'].append(f"Column '{col}' contains sensitive markers")

    # 3. Check for metadata in column comments or first row
    # Sometimes the first row contains metadata/instructions
    cursor.execute("SELECT * FROM sheet1 LIMIT 1")
    first_row = cursor.fetchone()

    if first_row:
        for i, cell in enumerate(first_row):
            if cell and isinstance(cell, str):
                cell_lower = str(cell).lower()
                if 'instruction' in cell_lower or 'directive' in cell_lower or 'note:' in cell_lower:
                    directives['data_handling_rules'].append(f"First row, column {sheet1_cols[i]}: {cell}")

    # Remove duplicates
    directives['restricted_columns'] = list(set(directives['restricted_columns']))

    return directives

